// Problem: Find if a user exists in a list by email

public boolean userExists(List<User> users, String email) {
    // Guard clause for null inputs
    if (users == null || email == null) {
        return false;
    }

    // Linear search through user list
    for (User user : users) {
        if (user.getEmail().equalsIgnoreCase(email)) {
            return true;  // Found match
        }
    }

    return false;  // No match found
}

// Example usage:
// var users = List.of(new User("alice@example.com"));
// boolean exists = userExists(users, "alice@example.com");

// Interviewer: "Find the first duplicate in an array"

// Candidate (speaking): "Okay, I'll use a HashSet to track seen elements.
// I'll iterate through the array, and for each number, check if it's
// already in the set. If yes, that's my duplicate. If no, I add it."

public Integer findFirstDuplicate(int[] numbers) {
    // Candidate: "First, let me handle the null case"
    if (numbers == null) {
        return null;
    }

    var seen = new HashSet<Integer>();

    // Candidate: "Now looping through each number..."
    for (int num : numbers) {
        // Candidate: "If seen already contains this, we found our duplicate"
        if (seen.contains(num)) {
            return num;
        }
        seen.add(num);
    }

    // Candidate: "If we finish the loop, there's no duplicate"
    return null;
}

// Interviewer: "Write a method to find the maximum value in a list"

// First attempt (with mistake):
public int findMax(List<Integer> numbers) {
    int max = 0;  // Candidate writes this

    for (int num : numbers) {
        if (num > max) {
            max = num;
        }
    }
    return max;
}

// Candidate (speaking): "Wait, I see an issue. If all numbers are negative,
// initializing max to zero will give the wrong answer. Let me fix that."

// Corrected version:
public int findMax(List<Integer> numbers) {
    if (numbers == null || numbers.isEmpty()) {
        throw new IllegalArgumentException("List cannot be empty");
    }

    int max = numbers.get(0);  // Fixed: start with first element

    for (int num : numbers) {
        if (num > max) {
            max = num;
        }
    }
    return max;
}

// Problem: Check if a string is a palindrome

// ===== PHASE 1-2: Understanding + Planning (10 min total) =====
// Candidate asks: "Should I ignore spaces and punctuation?"
// Candidate says: "I'll use two pointers from both ends moving inward"

// ===== PHASE 3: Coding (20 min) =====
public boolean isPalindrome(String text) {
    if (text == null || text.isEmpty()) {
        return true;  // Empty string is palindrome by definition
    }

    String cleaned = text.toLowerCase().replaceAll("[^a-z0-9]", "");

    int left = 0;
    int right = cleaned.length() - 1;

    while (left < right) {
        if (cleaned.charAt(left) != cleaned.charAt(right)) {
            return false;
        }
        left++;
        right--;
    }

    return true;
}

// ===== PHASE 4: Testing (5 min) =====
// Candidate traces: isPalindrome("A man, a plan, a canal: Panama")

OptionalInt findMax(int[] values) {
    if (values == null || values.length == 0) {
        return OptionalInt.empty();
    }

    int max = values[0];
    for (int i = 1; i < values.length; i++) {
        if (values[i] > max) max = values[i];
    }
    return OptionalInt.of(max);
}

